CREATE TABLE customers(id varchar(100) PRIMARY KEY,display_name varchar(200) NOT NULL,status varchar(20) NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id varchar(100) PRIMARY KEY,customer_id varchar(100) NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,currency char(3) NOT NULL DEFAULT 'JOD' CHECK(currency='JOD'),available_balance numeric(19,3) NOT NULL CHECK(available_balance>=0),opening_balance numeric(19,3) NOT NULL CHECK(opening_balance>=0),status varchar(20) NOT NULL CHECK(status IN('ACTIVE','FROZEN','CLOSED')),receive_enabled boolean NOT NULL DEFAULT true,transfer_limit numeric(19,3) NOT NULL DEFAULT 10000.000 CHECK(transfer_limit>0),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_permissions(principal varchar(200) NOT NULL,account_id varchar(100) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,can_debit boolean NOT NULL DEFAULT false,can_view boolean NOT NULL DEFAULT false,PRIMARY KEY(principal,account_id));
CREATE TABLE payments(payment_id uuid PRIMARY KEY,from_account_id varchar(100) NOT NULL,to_account_id varchar(100) NOT NULL,amount numeric(19,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL DEFAULT 'JOD' CHECK(currency='JOD'),instruction_date timestamptz NOT NULL,purpose varchar(255) NOT NULL,notes varchar(1000),payload_fingerprint char(64) NOT NULL,status varchar(20) NOT NULL CHECK(status IN('PENDING','COMPLETED','REJECTED')),rejection_code varchar(60),rejection_http integer,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,requested_by varchar(200) NOT NULL,correlation_id uuid NOT NULL);
CREATE INDEX payments_from ON payments(from_account_id,created_at);CREATE INDEX payments_to ON payments(to_account_id,created_at);CREATE INDEX payments_time ON payments(created_at);
CREATE TABLE ledger_entries(id bigserial PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments(payment_id) ON DELETE RESTRICT,account_id varchar(100) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,entry_type varchar(6) NOT NULL CHECK(entry_type IN('DEBIT','CREDIT')),signed_amount numeric(19,3) NOT NULL,balance_after numeric(19,3) NOT NULL CHECK(balance_after>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(payment_id,entry_type),CHECK((entry_type='DEBIT' AND signed_amount<0) OR(entry_type='CREDIT' AND signed_amount>0)));
CREATE INDEX ledger_account ON ledger_entries(account_id);
CREATE FUNCTION immutable_financial() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial record is immutable'; END $$;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_financial();
CREATE FUNCTION immutable_payment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status<>'PENDING' THEN RAISE EXCEPTION 'Final payment is immutable'; END IF;RETURN NEW;END $$;
CREATE TRIGGER payment_immutable BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION immutable_payment();
CREATE FUNCTION completed_ledger_check() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE n bigint;s numeric;BEGIN IF NEW.status='COMPLETED' THEN SELECT count(*),coalesce(sum(signed_amount),0) INTO n,s FROM ledger_entries WHERE payment_id=NEW.payment_id;IF n<>2 OR s<>0 THEN RAISE EXCEPTION 'Unbalanced completed payment'; END IF;END IF;RETURN NEW;END $$;
CREATE CONSTRAINT TRIGGER completed_balanced AFTER INSERT OR UPDATE ON payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION completed_ledger_check();
